import pandas as pd

def clean(df):
    # Fix category labels: strip spaces and standardize case
    df['Category'] = df['Category'].astype(str).str.strip()

    # Fix region labels: map known variants to standard names
    region_map = {
        'Suoth': 'South',
        'Nort': 'North'
    }
    df['Region'] = df['Region'].map(lambda x: region_map.get(x, x) if pd.notna(x) else x)

    # Filter for Electronics only
    df_electronics = df[df['Category'] == 'Electronics'].copy()

    # Group by region and sum revenue
    result = df_electronics.groupby('Region')['Revenue'].sum()

    # Convert to dict with region as key
    return result.to_dict()

def answer(df):
    return clean(df)
